
import type { MoneyValueInput } from './MoneyValueInput.js';

export type PaymentIntentInput = { /** Itemized invoice, subscription, and automatic tax fees collected with this payment. Available to the merchant only. Empty until fees settle or when no add-ons apply. Refunds do not return or revise these fees. */ "add_on_fees"?: never; "amount_money": MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "authorization_expires_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "authorized_at"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "authorized_money"?: never; /** Flint-normalized reason the payment intent was canceled. Unknown processor values are returned as payment_canceled. */ "cancellation_reason"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "capturable_money"?: never; "capture_method"?: "automatic" | "manual"; /** RFC3339 timestamp. Format: date-time. */ "captured_at"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "captured_money"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; /** Typed browser authority for the current standalone payment action. Complete it, then call the same confirm endpoint without a replacement credential. Absent when no browser action is required. */ "current_payment_action"?: never; "customer"?: never; "customer_id"?: string; "dispute_status"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_hold"?: never; "invoice"?: never; "invoice_id"?: never; "last_payment_error"?: never; "merchant_id"?: never; /** Captured amount minus processing_fee_money and every amount in add_on_fees. Later merchant assessments and credits are separate balance effects. */ "merchant_net_money"?: never; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; "origin"?: never; "payment_flow"?: never; "payment_intent_id"?: never; "payment_options": Array<"card" | "apple_pay" | "google_pay" | "affirm" | "ach_debit">; "payment_source"?: never; /** Flint's all-in processing fee for this payment. It is the complete price Flint charges to process the payment, never a provider cost passed through. The fee is final once the card payment is captured or the ACH payment succeeds; canceled payments and failures before success have none. Invoice, subscription, and automatic tax fees are itemized separately in add_on_fees. Your net for the payment is captured_money minus this fee and the add-on fees. Refunds do not return or revise it. */ "processing_fee_money"?: never; "receipt_email"?: string; "refund_status"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refunded_money"?: never; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "released_money"?: never; "risk"?: never; "selected_payment_option"?: never; "settlement_status"?: never; "status"?: never; /** Opaque payment reference to share with merchant support. Do not parse its format. */ "support_reference"?: never; "tip_money"?: MoneyValueInput; "transaction_purpose"?: "goods" | "services" | "other"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; };
